using System.Security.Cryptography;
using Microsoft.EntityFrameworkCore;
using SMSMarica.Data;
using SMSMarica.Data.Entities;

namespace SMSMarica.Api.Auth;

/// <summary>
/// Seed do cabeçalho institucional do laudo (CDT Maricá): um banner único
/// (Brasão de Maricá à esquerda, texto institucional ao centro, SUS RJ à
/// direita, com borda) no store de Mídia + HTML do cabeçalho na configuração
/// singleton. Banner único evita a discrepância de tamanho/layout entre o
/// editor (TipTap ignora width) e o PDF. Logos extraídas de
/// docs/FORMULA DE LAUDO CDT.docx; banner composto em 1240x300.
/// Idempotente: não sobrescreve cabeçalho já editado no painel.
/// </summary>
internal static class SeedCabecalhoLaudo
{
    private static readonly Guid BannerId = new("00000000-0000-0000-0000-00000000a003");

    // URL absoluta da API: a tag <img> é carregada pelo browser na origem do
    // front (smsmarica.online), mas o /midias mora na API — relativo apontaria
    // pro domínio errado (404). O endpoint é anônimo/público, então a URL
    // absoluta funciona em qualquer origem. Ver urlMidiaAbsoluta no front.
    private const string CabecalhoHtml = """
<p style="text-align: center"><img src="https://api.smsmarica.online/midias/00000000-0000-0000-0000-00000000a003" width="515"></p>
""";

    public static async Task GarantirAsync(SmsMaricaDbContext db, CancellationToken ct)
    {
        if (!await db.Midias.AnyAsync(m => m.Id == BannerId, ct))
        {
            var bytes = Convert.FromBase64String(BannerPngBase64);
            db.Midias.Add(new Midia
            {
                Id = BannerId,
                NomeArquivo = "cabecalho-cdt.png",
                MimeType = "image/png",
                Conteudo = bytes,
                TamanhoBytes = bytes.Length,
                Largura = 1240,
                Altura = 300,
                Categoria = "laudo-cabecalho",
                HashSha256 = Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant(),
                CriadoEm = DateTime.UtcNow,
            });
            await db.SaveChangesAsync(ct);
        }

        var cfg = await db.LaudoConfiguracoes
            .FirstOrDefaultAsync(x => x.Id == LaudoConfiguracao.IdSingleton, ct);

        if (cfg is null)
        {
            db.LaudoConfiguracoes.Add(new LaudoConfiguracao
            {
                Id = LaudoConfiguracao.IdSingleton,
                CabecalhoHtml = CabecalhoHtml,
                CabecalhoJson = "{}",
                RodapeHtml = string.Empty,
                RodapeJson = "{}",
                AtualizadoEm = DateTime.UtcNow,
            });
            await db.SaveChangesAsync(ct);
        }
        else if (string.IsNullOrWhiteSpace(cfg.CabecalhoHtml))
        {
            cfg.CabecalhoHtml = CabecalhoHtml;
            cfg.AtualizadoEm = DateTime.UtcNow;
            await db.SaveChangesAsync(ct);
        }
    }

    private const string BannerPngBase64 = "";
}
